inline void MessageStreamMessageDataView::GetAcknowledgementDataView(
    AcknowledgementMessageDataView* output) const {
  CHECK(is_acknowledgement());
  *output = AcknowledgementMessageDataView(data_->data.f_acknowledgement.Get(), message_);
}


